using System.Drawing;using System.Windows.Forms;namespace AshkanJobCenter.Core{public static class Theme{public static readonly Color Primary=Color.FromArgb(31,78,121),Accent=Color.FromArgb(20,145,155),Background=Color.FromArgb(245,248,252),Surface=Color.White,Text=Color.FromArgb(32,45,58),Muted=Color.FromArgb(102,116,132),Success=Color.FromArgb(37,135,92),Danger=Color.FromArgb(190,60,70),Border=Color.FromArgb(222,230,238);public static readonly Font Font=new Font("Segoe UI",10f);public static void Apply(Control c){c.Font=Font;c.ForeColor=Text;if(c is Form){c.BackColor=Background;((Form)c).StartPosition=FormStartPosition.CenterScreen;}foreach(Control x in c.Controls)Apply(x);}}}